CREATE INDEX idx_high_fidelity_mcr ON scanmesh (((facetfaces::float / NULLIF(facetverts, 0) / POWER(facetresmm, 2)) * 1000));

CREATE INDEX idx_high_fidelity_geomdeltamm ON scanmesh (geomdeltamm);

ANALYZE scanmesh;

CREATE OR REPLACE FUNCTION mesh_mcr(facetfaces bigint, facetverts bigint, facetresmm numeric) RETURNS numeric AS $$
SELECT (facetfaces::float / NULLIF(facetverts, 0) / POWER(facetresmm, 2)) * 1000;
$$ LANGUAGE SQL IMMUTABLE;

CREATE INDEX idx_high_fidelity_mcr ON scanmesh (mesh_mcr(facetfaces, facetverts, facetresmm));
